function secondsUntilDone(tickets: number[], k: number): number {
  const left = tickets.slice();
  let time = 0;
  while (true) {
    for (let i = 0; i < left.length; i++) {
      if (left[i] === 0) continue;
      left[i]--;
      time++;
      if (i === k && left[i] === 0) return time;
    }
  }
}

