function secondsUntilDone(tickets: number[], k: number): number {
  const t = tickets[k];
  let total = 0;
  for (let i = 0; i < tickets.length; i++) {
    total += Math.min(tickets[i], i <= k ? t : t - 1);
  }
  return total;
}

